#!/usr/bin/env python3
"""Install read-only push monitoring. Pass a root-owned enrollment JSON file.
No Docker, driver, power, reboot or workload changes are performed.
"""
import base64,json,os,pathlib,subprocess,sys,urllib.request,urllib.parse,pwd,grp,tempfile
AGENT = ''
UNIT = ''

def write(path,data,mode,group=0):
    p=pathlib.Path(path);p.parent.mkdir(parents=True,exist_ok=True)
    fd,tmp=tempfile.mkstemp(dir=p.parent)
    try:
        with os.fdopen(fd,'wb') as f:f.write(data)
        os.chmod(tmp,mode);os.chown(tmp,0,group);os.replace(tmp,p)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
def run(*args):subprocess.run(args,check=True,stdout=subprocess.DEVNULL)
def main():
    if os.geteuid()!=0 or len(sys.argv)!=2:raise SystemExit('Usage: sudo python3 monitoring-install.py /path/to/enrollment.json')
    source=pathlib.Path(sys.argv[1]);st=source.stat()
    if st.st_uid!=0 or st.st_mode & 0o077:raise SystemExit('Enrollment file must be owned by root with permissions 0600')
    cfg=json.loads(source.read_text());url=cfg['url'].rstrip('/')
    u=urllib.parse.urlsplit(url)
    if u.scheme!='https' or not u.hostname or u.username or u.password or u.query or u.fragment:raise SystemExit('A trusted HTTPS receiver is required')
    req=urllib.request.Request(url+'/v1/enroll',data=b'',headers={'Authorization':'Bearer '+cfg['enrollment']},method='POST')
    with urllib.request.urlopen(req,timeout=20) as r:enrolled=json.loads(r.read(8192))
    try:pwd.getpwnam('infrastructure-monitor')
    except KeyError:run('useradd','--system','--no-create-home','--shell','/usr/sbin/nologin','infrastructure-monitor')
    run('usermod','-a','-G','systemd-journal','infrastructure-monitor')
    group=grp.getgrnam('infrastructure-monitor').gr_gid
    config={'url':url,'node':enrolled['node'],'token':enrolled['token'],'gpu_uuids':[]}
    write('/etc/infrastructure-monitor/config.json',json.dumps(config).encode(),0o640,group)
    write('/opt/infrastructure-monitor/agent.py',base64.b64decode(AGENT),0o755)
    write('/etc/systemd/system/infrastructure-monitor.service',base64.b64decode(UNIT),0o644)
    run('systemctl','daemon-reload');run('systemctl','enable','infrastructure-monitor.service');run('systemctl','restart','infrastructure-monitor.service')
    source.unlink()
    print('Monitoring installed. Follow: journalctl -u infrastructure-monitor.service')
if __name__=='__main__':
    try:main()
    except Exception as e:
        print('ERROR: Monitoring installation failed: '+type(e).__name__,file=sys.stderr);sys.exit(1)
